import { createContext, useContext, useEffect, useMemo, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react';
import { useAppState } from '../../app/AppState';
import { visualStyleLabel } from '../project/styles';
import { Badge, Button, Card, CardHeader, Field, Input, Textarea } from '../../components/ui';
const tabs = ['Script', 'Native'] as const; type PromptTab = (typeof tabs)[number]; type SyntaxResult = 'idle' | 'valid' | 'invalid';
interface ExternalSession { tab: PromptTab; setTab: Dispatch<SetStateAction<PromptTab>>; json: string; setJson: Dispatch<SetStateAction<string>>; result: SyntaxResult; setResult: Dispatch<SetStateAction<SyntaxResult>> }
const Context = createContext<ExternalSession | null>(null);
export function ExternalSessionProvider({ children }: { children: ReactNode }) { const [tab,setTab]=useState<PromptTab>('Script'); const [json,setJson]=useState(''); const [result,setResult]=useState<SyntaxResult>('idle'); return <Context.Provider value={{tab,setTab,json,setJson,result,setResult}}>{children}</Context.Provider>; }
const useSession=()=>{const value=useContext(Context);if(!value)throw new Error('ExternalSessionProvider missing');return value;};
const fallbackPrompt=(tab:PromptTab,style:string)=>`# MODE B EXTERNAL CHATGPT — ${tab.toUpperCase()}\n\nManual transport only. Return exactly one UTF-8 JSON object.\n\nStyle contract: ${style}\nDEMO: open a native project to include real source material and the frozen schema.`;
export function ExternalWorkspace(){
  const {tab,setTab,json,setJson,result,setResult}=useSession(); const {project,native,setNative,showNotice}=useAppState(); const [prompt,setPrompt]=useState(''); const [pending,setPending]=useState<{token:string;before:unknown;after:unknown;changes:number;status:string;missing?:Array<{key:string;kind:string;path:string}>}|null>(null); const [error,setError]=useState('');const [previewSeconds,setPreviewSeconds]=useState(20);const [draftConsent,setDraftConsent]=useState(false); const stage=tab.toLowerCase();
  const demo=useMemo(()=>fallbackPrompt(tab,visualStyleLabel(project.style)),[tab,project.style]);
  useEffect(()=>{let active=true;if(native&&window.studio)window.studio.freezeTask(native.project.id,stage).then(value=>{if(active)setPrompt(value.prompt)}).catch(reason=>{if(active){setError(String(reason));setPrompt('')}});else setPrompt(demo);return()=>{active=false};},[native,stage,demo]);
  const change=(value:string)=>{setJson(value);setResult('idle');setPending(null);setDraftConsent(false);setError('');};
  const refreshPending=async()=>{if(!native||!window.studio||stage!=='native')return;try{const value=await window.studio.pendingMedia(native.project.id);setPending(value as typeof pending);setError('');}catch(reason){setError(String(reason));}};
  const validate=async()=>{try{if(native&&window.studio){const value=await window.studio.stageImport(native.project.id,stage,json);setPending(value);setResult('valid');}else{const parsed:unknown=JSON.parse(json);setResult(parsed!==null&&typeof parsed==='object'&&!Array.isArray(parsed)?'valid':'invalid');}}catch(reason){setResult('invalid');setError(reason instanceof Error?reason.message:String(reason));}};
  const copy=()=>navigator.clipboard.writeText(prompt).then(()=>showNotice(`${tab} prompt copied.`)).catch(()=>showNotice('Clipboard unavailable.'));
  const exportFile=async()=>{if(native&&window.studio){const file=await window.studio.exportPrompt(native.project.id,stage);if(file)showNotice(`Prompt exported: ${file}`);return;}const blob=new Blob([prompt],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`mode-b-${stage}-demo.md`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),0);};
  return <div className="grid wide-left"><Card><CardHeader title="External task prompt" hint="Copy to ChatGPT manually · no embedded API" action={<Badge tone={native?'mint':'amber'}>{native?'FROZEN':'DEMO'}</Badge>}/><div className="tabs">{tabs.map(item=><button key={item} className={tab===item?'active':''} onClick={()=>setTab(item)}>{item}</button>)}</div><pre className="prompt" data-active-prompt={tab}>{prompt}</pre><div className="actions"><Button variant="primary" onClick={copy}>Copy prompt</Button><Button onClick={exportFile}>Export .md</Button><Button onClick={()=>window.open('https://chatgpt.com/','_blank','noopener,noreferrer')}>Open ChatGPT</Button></div></Card>
    <Card><CardHeader title="Import JSON workspace" hint="Strict schema · diff · explicit confirmation"/><Textarea aria-label="Import JSON" value={json} onChange={event=>change(event.target.value)} placeholder="Paste the returned JSON here…"/><div className="actions"><Button disabled={!json} onClick={()=>change('')}>Clear</Button><Button variant="primary" onClick={validate}>{native?'Validate import':'Validate syntax demo'}</Button></div>
      {result==='valid'&&<div className="info success">{native?'Schema valid. Review the staged diff before import.':'Valid JSON syntax · DEMO ONLY. No artifact was imported or accepted.'}</div>}{result==='invalid'&&<div className="info error" role="alert">{native?'Invalid import.':'Invalid JSON.'} {error}</div>}
      {pending&&<><div className="diff-grid"><pre className="prompt">BEFORE{`\n`}{JSON.stringify(pending.before,null,2)}</pre><pre className="prompt">AFTER{`\n`}{JSON.stringify(pending.after,null,2)}</pre></div>
        {stage==='native'&&<><div className="info">Original Mode B validates the selected sample with --seconds N. FULL_READY requires separate unscoped native validation. Media outside the scoped sample may remain incomplete only for an explicitly approved draft.</div>
          <Field label="Owner-selected preview seconds (1–60)"><Input type="number" min={1} max={60} value={previewSeconds} onChange={event=>setPreviewSeconds(Number(event.target.value))}/></Field>
          <label className="check"><input type="checkbox" checked={draftConsent} onChange={event=>setDraftConsent(event.target.checked)}/> I explicitly authorize an incomplete SAMPLE_READY draft, not full-film readiness.</label>
          <Button onClick={refreshPending}>Refresh missing media after mapping</Button>
          {pending.missing?.length? <div className="info">Unresolved native targets: {pending.missing.map(item=>item.key+' ('+item.path+')').join(', ')}. Select each precise target in Storyboard; only in-scope missing media blocks the sample.</div>:<div className="info success">No unresolved file targets recorded; the original scoped/full CLI will still verify native integrity.</div>}
        </>}
        <Button variant="primary" onClick={async()=>{if(!window.studio||!native)return;try{const state=await window.studio.confirmImport(native.project.id,pending.token,stage==='native'?{previewSeconds,allowSampleDraft:draftConsent}:undefined);setNative(state);setPending(null);showNotice(stage==='native'?(state.nativeReadiness?.fullReady?'FULL_READY · original native validator PASS.':'SAMPLE_READY draft · not full render ready.'):`${tab} revision imported.`);}catch(reason){setError(String(reason));}}}>Confirm reviewed import {stage==='native'?'(original native CLI validation)':''}</Button>
      </>}
      {native?.nativeReadiness&&<div className="info">Persisted native readiness: {native.nativeReadiness.fullReady?'FULL_READY':native.nativeReadiness.sampleReady?'SAMPLE_READY draft':'NOT_READY'} · verified range {native.nativeReadiness.checkedSeconds??'unknown'}s · latest requested {native.nativeReadiness.previewSeconds}s.</div>}
      {!native&&<div className="info">Open a native project to persist revisions under .studio/external.</div>}
    </Card></div>;
}
